// #2032 — past 1e100 the BigFloat reference orbit stops at the period when the reference
// lies within a pixel of a period-n nucleus by Newton distance (|Z_n / Z'_n| < pixel) and
// |Z_n| has fallen half-way to the pixel scale (|Z_n|^4 < pixel^2), not only when |Z_n| < pixel.
// The bench-kit minibrot centre sits in the attracting cycle (|Z_p|^2 ~ 2^-3451, pixel^2
// ~ 2^-6659), so the |Z_n| test never fired and the orbit ran to the cap (30 periods).
// Locations: the fractadyne bench-kit ladder by WindySnowOwl (Apache-2.0; bibliography
// #fractadyne-bench-kit, THIRD-PARTY-NOTICES.md section 6), with the caps cut to keep the
// tests short. Mutants: dropping the Newton test (the minibrot runs to its cap) and dropping
// the |Z_n|^4 guard (the spiral reports a period near its escape) each fail a test here.

using System;
using FracturingFog.Models;
using FracturingFog.ViewState;
using Xunit;

namespace FracturingFog.Server.Tests;

[Collection(MandelbrotGpuStaticsCollection.Name)]   // writes MandelbrotCalculator.PeriodicReferenceOrbit
public sealed class S2032ApPeriodTests
{
    private const int W = 48, H = 27;

    // 44-mini-p14416-1e1001.kfr (period 14,416 at 1e1000).
    internal const string MiniRe = "-2.-2";
    internal const string MiniIm = "6.-1";
    internal const string MiniZoom = "3.443499E1000";

    // 52-path-1e1000.kfr (a spiral path at 1e1000: not periodic, escapes).
    internal const string PathRe = "-2.-2";
    internal const string PathIm = "6.-1";
    internal const string PathZoom = "1.000000E1000";

    internal static MandelbrotCalculator Calc(string re, string im, string zoom, int maxIter, bool periodic)
    {
        string kfr = string.Join(Environment.NewLine, $"Re: {re}", $"Im: {im}", $"Zoom: {zoom}", $"Iterations: {maxIter}");
        Assert.True(KfrLocation.TryParse(kfr, out var loc, out var err), err);
        var (x, y) = loc!.Centre();
        double zl = loc.FfZoomLog10(W, H);
        var c = new MandelbrotCalculator(W, H)
        {
            Quality = QualityPreset.Unbounded,
            CenterX = x[0], CenterXLo = x[1], CenterX2 = x[2], CenterX3 = x[3],
            CenterX4 = x[4], CenterX5 = x[5], CenterX6 = x[6], CenterX7 = x[7],
            CenterY = y[0], CenterYLo = y[1], CenterY2 = y[2], CenterY3 = y[3],
            CenterY4 = y[4], CenterY5 = y[5], CenterY6 = y[6], CenterY7 = y[7],
            Zoom = 1e300, MaxIterations = maxIter,
        };
        c.SetDepth(loc.CentreExact(), zl);
        bool saved = MandelbrotCalculator.PeriodicReferenceOrbit;
        MandelbrotCalculator.PeriodicReferenceOrbit = periodic;
        try { c.Calculate(); } finally { MandelbrotCalculator.PeriodicReferenceOrbit = saved; }
        return c;
    }

    [Fact]
    public void An_Attracting_Cycle_Minibrot_Centre_Stops_At_The_Period_And_Renders_The_Same()
    {
        const int cap = 3 * 14416 + 1000;
        var on = Calc(MiniRe, MiniIm, MiniZoom, cap, periodic: true);
        var off = Calc(MiniRe, MiniIm, MiniZoom, cap, periodic: false);
        Assert.Equal(14416, on.ReferencePeriod);
        Assert.Equal(14417, on.ReferenceOrbitLength);
        Assert.Equal(0, off.ReferencePeriod);
        Assert.True(off.ReferenceOrbitLength >= cap - 1, $"full orbit {off.ReferenceOrbitLength}");
        int diff = 0, inOut = 0;
        for (int i = 0; i < W * H; i++)
        {
            if (on.IterationBuffer[i] != off.IterationBuffer[i]) diff++;
            if ((on.IterationBuffer[i] >= cap) != (off.IterationBuffer[i] >= cap)) inOut++;
        }
        Assert.Equal(0, inOut);
        Assert.True(diff <= W * H * 3 / 100, $"{diff}/{W * H} iteration counts differ");   // #1614's bound
    }

    [Fact]
    public void An_Escaping_Spiral_Reference_Keeps_Its_Full_Orbit_And_Renders_Byte_Identically()
    {
        const int cap = 30000;
        var on = Calc(PathRe, PathIm, PathZoom, cap, periodic: true);
        var off = Calc(PathRe, PathIm, PathZoom, cap, periodic: false);
        Assert.Equal(0, on.ReferencePeriod);
        Assert.Equal(off.ReferenceOrbitLength, on.ReferenceOrbitLength);
        Assert.Equal(off.IterationBuffer, on.IterationBuffer);
        Assert.Equal(off.SmoothBuffer, on.SmoothBuffer);
        Assert.Equal(off.ColorBuffer, on.ColorBuffer);
    }
}
